 "content": "def transform(grid):
    """Connect diagonal point pairs; an on-segment foreign mark emits the crossing diagonal."""
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    out = [row[:] for row in grid]
    original = [row[:] for row in grid]
    colors = {value for row in grid for value in row if value != background}
    segments = []

    # Join every diagonal pair of points in the same color.
    for color in colors:
        points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for i, (r, c) in enumerate(points):
            for rr, cc in points[i + 1:]:
                if abs(rr - r) == abs(cc - c):
                    dr = 1 if rr > r else -1
                    dc = 1 if cc > c else -1
                    segment = [(r + k * dr, c + k * dc) for k in range(abs(rr - r) + 1)]
                    segments.append((color, segment))
                    for y, x in segment:
                        out[y][x] = color

    # A point of another color lying on a segment creates the perpendicular
    # diagonal through that point. Keep all original marks unchanged.
    for line_color, segment in segments:
        segment_set = set(segment)
        for color in colors - {line_color}:
            for r in range(h):
                for c in range(w):
                    if original[r][c] == color and (r, c) in segment_set:
                        for dr, dc in ((1, 1), (1, -1)):
                            y, x = r, c
                            while 0 <= y < h and 0 <= x < w:
                                out[y][x] = color
                                y += dr
                                x += dc
                            y, x = r - dr, c - dc
                            while 0 <= y < h and 0 <= x < w:
                                out[y][x] = color
                                y -= dr
                                x -= dc

    # Original colored points take priority where drawn lines cross.
    for r in range(h):
        for c in range(w):
            if original[r][c] != background:
                out[r][c] = original[r][c]
    return out
