 "content": "def transform(grid):
    """Join diagonal pairs; marks on a pair's segment emit a perpendicular line."""
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v != background}
    segments = []

    # Find and fill each finite diagonal segment between aligned same-color marks.
    for color in colors:
        points = [(r, c) for r in range(h) for c in range(w) if original[r][c] == color]
        for i, (r, c) in enumerate(points):
            for rr, cc in points[i + 1:]:
                if abs(rr - r) == abs(cc - c):
                    dr = 1 if rr > r else -1
                    dc = 1 if cc > c else -1
                    cells = [(r + k * dr, c + k * dc) for k in range(abs(rr - r) + 1)]
                    segments.append((color, dr, dc, set(cells)))
                    for y, x in cells:
                        out[y][x] = color

    # A different-color seed lying on a segment extends on the perpendicular
    # diagonal, in both directions, clipped to the grid.
    for line_color, dr, dc, segment in segments:
        for marker_color in colors - {line_color}:
            for r in range(h):
                for c in range(w):
                    if original[r][c] != marker_color or (r, c) not in segment:
                        continue
                    for sr, sc in ((dr, -dc), (-dr, dc)):
                        y, x = r, c
                        while 0 <= y < h and 0 <= x < w:
                            out[y][x] = marker_color
                            y += sr
                            x += sc

    # Reapply finite pair segments in fixed priority order (higher color first,
    # then lower color), so the primary lower-color path wins at intersections.
    for color in sorted(colors, reverse=True):
        points = [(r, c) for r in range(h) for c in range(w) if original[r][c] == color]
        for i, (r, c) in enumerate(points):
            for rr, cc in points[i + 1:]:
                if abs(rr - r) == abs(cc - c):
                    dr = 1 if rr > r else -1
                    dc = 1 if cc > c else -1
                    for k in range(abs(rr - r) + 1):
                        out[r + k * dr][c + k * dc] = color

    # Input seeds are never changed even when projected lines cross them.
    for r in range(h):
        for c in range(w):
            if original[r][c] != background:
                out[r][c] = original[r][c]
    return out
